/**
 * Mirroring for right-to-left locales (GDD 26.1, ARCHITECTURE 9): UI Toolkit shapes RTL text but
 * does not mirror layout, so every stylesheet rule that lays children out in a row, or aligns text
 * left or right, gets a `.rtl` twin that reverses it. The shell puts `rtl` on the root for an RTL
 * locale. Generated into Theme/Rtl.uss by `pnpm codegen`; do not edit that file.
 */
interface Rule {
  readonly selectors: readonly string[];
  readonly body: string;
}

function rulesOf(uss: string): Rule[] {
  const clean = uss.replace(/\/\*[\s\S]*?\*\//g, "");
  const rules: Rule[] = [];
  for (const match of clean.matchAll(/([^{}]+)\{([^{}]*)\}/g)) {
    const selectors = (match[1] ?? "")
      .split(",")
      .map((s) => s.trim())
      .filter((s) => s !== "" && !s.startsWith(":root") && !s.startsWith("@"));
    rules.push({ selectors, body: match[2] ?? "" });
  }
  return rules;
}

const FLIP: Readonly<Record<string, string>> = {
  row: "row-reverse",
  "row-reverse": "row",
  "upper-left": "upper-right",
  "upper-right": "upper-left",
  "middle-left": "middle-right",
  "middle-right": "middle-left",
  "lower-left": "lower-right",
  "lower-right": "lower-left",
};

export function rtlStyles(sheets: Readonly<Record<string, string>>): string {
  const out: string[] = [
    "/* Generated by tools/strings-export (pnpm codegen) from the stylesheets below; do not edit. */",
    "",
    "/* Text with no alignment of its own starts from the right. */",
    ".rtl .unity-label {\n    -unity-text-align: upper-right;\n}",
  ];
  for (const [name, uss] of Object.entries(sheets)) {
    const lines: string[] = [];
    for (const rule of rulesOf(uss)) {
      if (rule.selectors.length === 0) continue;
      const declarations: string[] = [];
      const direction = /flex-direction:\s*(row-reverse|row)\s*;/.exec(rule.body)?.[1];
      if (direction !== undefined)
        declarations.push(`flex-direction: ${FLIP[direction] ?? direction};`);
      const align = /-unity-text-align:\s*([a-z-]+)\s*;/.exec(rule.body)?.[1];
      // Centred rules are repeated so they still win over the right-aligned default below.
      if (align !== undefined) declarations.push(`-unity-text-align: ${FLIP[align] ?? align};`);
      if (declarations.length === 0) continue;
      const selectors = rule.selectors.map((s) => `.rtl ${s}`).join(",\n");
      lines.push(`${selectors} {\n    ${declarations.join("\n    ")}\n}`);
    }
    if (lines.length > 0) out.push(`\n/* ${name} */\n${lines.join("\n\n")}`);
  }
  return `${out.join("\n")}\n`;
}
